@prefix ex: <http://example.org/> .
@prefix ns2: <http://example.org/ns2/> .
@prefix ns3: <http://example.org/ns3/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .

ex:oven a ex:Oven ;
    rdfs:label "The oven" ;
    ex:locatedWithin ex:southernmost_shop .

ex:domus a ns2:CACAO_0000055 ;
    rdfs:label "domus" ;
    ns3:P129i_is_subject_of ex:domus ;
    ns3:P130i_features_are_also_found_on ex:domus ;
    ns3:P138i_has_representation ex:domus ;
    ns3:P1i_identifies ex:domus ;
    ns3:P67i_is_referred_to_by ex:domus .

ex:southernmost_shop a ex:Shop ;
    rdfs:label "the southernmost shop" ;
    ex:partOf ex:domus ;
    ex:usedAs ex:bakery .

ex:bakery a ex:Bakery ;
    rdfs:label "bakery" .

ex:lower_part_oven a ns3:E54_Dimension ;
    rdfs:label "lower part, circular inside, of the oven" ;
    ex:partOf ex:oven ;
    ex:hasDimension ex:circular_inside .

ex:circular_inside a ns3:E54_Dimension ;
    rdfs:label "circular inside" ;
    ns3:P190_has_symbolic_content ex:circular_inside ;
    ns3:P40i_was_observed_in ex:circular_inside .

ex:brick_base a ns3:E57_Material ;
    rdfs:label "brick base" ;
    ex:madeOf ex:brick ;
    ex:supports ex:millstone .

ex:brick a ns3:E57_Material ;
    rdfs:label "brick" ;
    ns3:P129i_is_subject_of ex:brick ;
    ns3:P130i_features_are_also_found_on ex:brick ;
    ns3:P138i_has_representation ex:brick ;
    ns3:P1i_identifies ex:brick ;
    ns3:P45i_is_incorporated_in ex:brick ;
    ns3:P67i_is_referred_to_by ex:brick .

ex:millstone a ex:Millstone ;
    rdfs:label "millstone" ;
    ex:usedFor ex:grinding_wheat .

ex:grinding_wheat a ex:Activity ;
    rdfs:label "grinding wheat" .

ex:counter a ex:Counter ;
    rdfs:label "counter" ;
    ex:usedFor ex:preparing_bread .

ex:preparing_bread a ex:Activity ;
    rdfs:label "preparing bread" .

ex:sale a ex:Sale ;
    rdfs:label "sale" ;
    ex:tookPlaceOn ex:eastern_cardo .

ex:eastern_cardo a ns3:E53_Place ;
    rdfs:label "eastern cardo" ;
    ns3:P12i_was_present_at ex:eastern_cardo ;
    ns3:P53i_is_former_or_current_location_of ex:eastern_cardo ;
    ns3:P55i_currently_holds ex:eastern_cardo ;
    ns3:P7i_witnessed ex:eastern_cardo ;
    ns3:P89i_contains ex:eastern_cardo .
